def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or not domain
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return local + "@" + domain

    def normalize_phone(value):
        value = value or ""
        extension = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if extension:
            value = value[:extension.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = (value or "").strip()
        if "-" in value:
            value = value.split("-", 1)[0]

        if len(value) == 4 and value.isdigit():
            value = "0" + value

        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated date: {!r}".format(value))

    def is_opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    normalized = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))

        # Ineligible rows do not participate in matching or output.
        if not email and not phone:
            continue

        normalized.append({
            "input_index": input_index,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row.get("zip", "")),
            "source": (row.get("source", "") or "").strip().lower(),
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": is_opted_out(row.get("opted_out", "")),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row.get("tags", "") or "")
                if tag.strip()
            },
        })

    # Union-find for transitive matching.
    parent = list(range(len(normalized)))
    rank = [0] * len(normalized)

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return

        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a

        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    email_owner = {}
    phone_last_name_owner = {}

    for index, row in enumerate(normalized):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = index
            else:
                union(index, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index, row in enumerate(normalized):
        groups.setdefault(find(index), []).append(row)

    def choose(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["input_index"],
            ),
        )
        return best[field]

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["input_index"] for row in group),
    )

    result = []
    for group in ordered_groups:
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated_dt"] for row in group)

        result.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return result
